mapper.insert:



      /* !!!!!!  아래 키를 가져오는 부분은 Sequence Table을 이용해서 Nextval을 활용하여 키를 가져와야 합니다. */
      /* 아래 로직은 수정이 필요함. */
      SELECT TO_CHAR(SYSDATE,'YYYYMMDD')||'_'|| TO_CHAR(NVL(COUNT(EMPYMN_QLFC_MNG_NO), 0) +1) AS EMPYMN_QLFC_MNG_NO
        FROM CYS_LICENCE
       WHERE CASE_MNG_NO = #{CASE_MNG_NO}




/* isry.pubmt.indivsprt.mapper.certimapper.insertCertiList  */

INSERT INTO CYS_LICENCE /* 권한 */
(
    CASE_MNG_NO
   ,CASE_MNG_ODRNO
   ,EMPYMN_QLFC_MNG_NO
   ,TASKWK_SE_CD
   ,EMPYMN_INST_NM 
   ,WORK_BGNG_YMD
   ,WORK_END_YMD
   ,RETIRE_CS_CN
   ,EMPYMN_TYPE_SE_CD
   ,ACQS_CERTI_NM
   ,ACQS_YMD 
   ,CONSTT_ID
   ,RGN_CD 
   ,INST_CD 
   ,ISSU_INST_NM 
   ,RTRM_YMD 
   ,CN1
   ,FRST_RGTR_ID
   ,FRST_REG_DT
)
VALUES
(
    #{CASE_MNG_NO}
   ,#{CASE_MNG_ODRNO}
   ,#{NEW_EMPYMN_QLFC_MNG_NO}
   ,#{TASKWK_SE_CD}
   ,#{EMPYMN_INST_NM} 
   ,#{WORK_BGNG_YMD}
   ,#{WORK_END_YMD}
   ,#{RETIRE_CS_CN}
   ,#{EMPYMN_TYPE_SE_CD}
   ,#{ACQS_CERTI_NM}
   ,#{ACQS_YMD}
   ,#{CONSTT_ID}
   ,#{RGN_CD}
   ,#{INST_CD}
   ,#{ISSU_INST_NM}
   ,#{RTRM_YMD}
   ,#{CN1}
   ,#{FRST_RGTR_ID}
   ,SYSDATE
)

mapper.update:

/* isry.pubmt.indivsprt.mapper.certimapper.updateCertiList  */
UPDATE CYS_LICENCE SET
   TASKWK_SE_CD = #{TASKWK_SE_CD}
   ,EMPYMN_INST_NM = #{EMPYMN_INST_NM}
   ,WORK_BGNG_YMD = #{WORK_BGNG_YMD}
   ,WORK_END_YMD = #{WORK_END_YMD}
   ,RETIRE_CS_CN = #{RETIRE_CS_CN}
   ,EMPYMN_TYPE_SE_CD = #{EMPYMN_TYPE_SE_CD}
   ,ACQS_CERTI_NM = #{ACQS_CERTI_NM}
   ,ACQS_YMD  = #{ACQS_YMD}
   ,CONSTT_ID = #{CONSTT_ID}
   ,RGN_CD  = #{RGN_CD}
   ,INST_CD  = #{INST_CD}
   ,ISSU_INST_NM  = #{ISSU_INST_NM}
   ,RTRM_YMD  = #{RTRM_YMD}
   ,CN1 = #{CN1}
   ,LAST_MDFR_ID = #{LAST_MDFR_ID}
   ,LAST_MDFCN_DT = SYSDATE
WHERE CASE_MNG_NO = #{CASE_MNG_NO}
  AND EMPYMN_QLFC_MNG_NO = #{EMPYMN_QLFC_MNG_NO}

mapper.delete:

/* isry.pubmt.indivsprt.mapper.certimapper.deleteCertiList  */
DELETE
FROM CYS_LICENCE
WHERE CASE_MNG_NO = #{CASE_MNG_NO}
  AND EMPYMN_QLFC_MNG_NO = #{EMPYMN_QLFC_MNG_NO}
